import React, { useState } from 'react';

interface UserSelectorProps {
  currentUserId: string;
  onUserChange: (userId: string) => void;
  onNewUser: (userId: string) => void;
}

const defaultUsers = [
  { id: 'user1', name: '小明', avatar: '👦' },
  { id: 'user2', name: '小红', avatar: '👧' },
  { id: 'user3', name: '小李', avatar: '👨' },
];

export const UserSelector: React.FC<UserSelectorProps> = ({ currentUserId, onUserChange, onNewUser }) => {
  const [showNewUserForm, setShowNewUserForm] = useState(false);
  const [newUserName, setNewUserName] = useState('');

  const handleAddUser = () => {
    if (newUserName.trim()) {
      const newUserId = `user_${Date.now()}`;
      onNewUser(newUserId);
      setNewUserName('');
      setShowNewUserForm(false);
    }
  };

  return (
    <div className="user-selector">
      <div className="user-selector-title">👤 用户选择</div>
      <div className="user-list">
        {defaultUsers.map((user) => (
          <div
            key={user.id}
            className={`user-item ${currentUserId === user.id ? 'active' : ''}`}
            onClick={() => onUserChange(user.id)}
          >
            <span className="user-avatar">{user.avatar}</span>
            <span className="user-name">{user.name}</span>
          </div>
        ))}
      </div>

      {!showNewUserForm ? (
        <button className="add-user-btn" onClick={() => setShowNewUserForm(true)}>
          + 添加新用户
        </button>
      ) : (
        <div className="new-user-form">
          <input
            type="text"
            value={newUserName}
            onChange={(e) => setNewUserName(e.target.value)}
            placeholder="输入用户名"
            className="new-user-input"
            autoFocus
          />
          <div className="new-user-actions">
            <button className="submit-btn" onClick={handleAddUser}>确定</button>
            <button className="cancel-btn" onClick={() => setShowNewUserForm(false)}>取消</button>
          </div>
        </div>
      )}
    </div>
  );
};
